test:
items = SnapshotSet()
assert items.add('x') is True
first = items.snapshot()
assert items.add('x') is False
second = items.snapshot()
assert second > first
assert items.remove('missing') is False
assert items.values_at(second) == {'x'}
for invalid in (True, -1, 99):
    try:
        items.values_at(invalid)
        assert False
    except IndexError:
        pass
try:
    items.add([])
    assert False
except TypeError:
    pass
